using Amazon.CloudWatch;
using Amazon.CloudWatch.Model;

var cloudWatch = new AmazonCloudWatchClient(RegionEndpoint.USEast1);

var putMetricRequest = new PutMetricDataRequest
{
    Namespace = "AspNetCore/MyApp",
    MetricData = new List<MetricDatum>
    {
        new MetricDatum
        {
            MetricName = "OrderCount",
            Value = 1,
            Unit = StandardUnit.Count,
            Timestamp = DateTime.UtcNow
        }
    }
};

await cloudWatch.PutMetricDataAsync(putMetricRequest);

public class PostsController : ControllerBase
{
    private readonly ILogger<PostsController> _logger;
    private readonly BlogContext _db;

    public PostsController(ILogger<PostsController> logger, BlogContext db)
    {
        _logger = logger;
        _db = db;
    }

    [HttpGet("{id}")]
    public async Task<ActionResult<Post>> Get(int id)
    {
        _logger.LogInformation("Fetching post {PostId} from RDS", id);
        var post = await _db.Posts.FindAsync(id);

        if (post is null)
        {
            _logger.LogWarning("Post {PostId} not found", id);
            return NotFound();
        }

        return Ok(post);
    }
}
